(function(){
'use strict';
if(window.__bpfRevisaoFAtiva)return;
window.__bpfRevisaoFAtiva=true;
const DATA={"schema":"bpf-appcc-revisao-orientacoes-v1","escopo":"Orientações e exemplos OBS/NC revisados e 5 definições; sem importar nem substituir redações legais. Itens 4.10.1, 4.11.1, 4.11.3 e 4.11.4 mantêm somente F1, com o conteúdo do F2 incorporado ao F1.","origem":"Revisão 07/11/2026; quatro F2 reunificados em F1 a pedido do usuário","preservar_frases_legais":true,"definicoes":{"PPR":"PPR — Programa de Pré-Requisitos — A ISO 22000 e o Codex Alimentarius definem o PPR como o conjunto de condições básicas e atividades de higiene necessárias para manter um ambiente limpo e seguro ao longo de toda a cadeia produtiva.","POP":"POP — Procedimento Operacional Padronizado — É um documento técnico e detalhado que descreve o passo a passo de uma atividade ou processo para garantir a sua padronização, qualidade e segurança, independentemente de quem o execute.","PC":"PC — Ponto de Controle — Qualquer etapa na cadeia produtiva onde fatores biológicos, químicos ou físicos podem ser monitorados, mas cuja perda de controle não gera um risco crítico imediato.","PPRO":"PPRO — Programa de Pré-Requisito Operacional — É uma medida de controle (ou combinação de medidas) identificada pela análise de perigos como essencial para controlar a probabilidade de introduzir, contaminar ou proliferar perigos à segurança de alimentos no produto ou no ambiente de processo. Uma falha em um PPRO normalmente não significa que o lote inteiro esteja imediatamente comprometido a ponto de causar dano grave sem chance de correção, embora exija ação corretiva.","PCC":"PCC — Ponto Crítico de Controle — Etapa em que o controle é essencial para prevenir ou eliminar um perigo significativo à segurança do alimento, ou reduzi-lo a um nível aceitável, mediante limites críticos e monitoramento. É validado obrigatoriamente por parâmetros mensuráveis chamados “limites críticos”."},"verificacoes":[{"item":"4.1.1","f":"F1","descricao_F":"","classificacao_appcc":"PPR","desdobramento":"A área circundante à casa de proteção da captação deve ser pavimentada, mantida limpa e livre de focos de insalubridade.","orientacao_inspetor":"Verifique se a área ao redor da casa de proteção da captação possui piso impermeável e íntegro. Certifique-se de que esteja limpa, sem mato alto ou entulhos, e livre de focos de insalubridade, lixo ou presença de gado e outros animais, para evitar a contaminação da água mineral.","obs_sim":"Foi constatado pavimento íntegro, limpo, sem vegetação invasiva ou resíduos no entorno da captação [código], com drenagem funcional.","nc_nao":"Na área circundante à captação [código], foram encontrados trechos de pavimentação quebrados, ausência de rejunte, vegetação crescendo nas fissuras e resíduos de obras; registrar fotografias e localização."},{"item":"4.1.1","f":"F2","descricao_F":"","classificacao_appcc":"PPR","desdobramento":"Deve dispor de um sistema de drenagem de águas pluviais de modo a impedir a infiltração de contaminantes, não comprometendo a qualidade sanitária da água mineral natural e da água natural.","orientacao_inspetor":"Verifique se o sistema de drenagem de águas pluviais ao redor da captação e da área de envase está íntegro e direcionado para evitar empoçamentos e infiltrações, prevenindo o carreamento de contaminantes que possam comprometer a qualidade sanitária da água mineral e natural.","obs_sim":"Na captação [código], verificou-se drenagem das águas pluviais por [canaleta/sistema], sem empoçamento ou infiltração.","nc_nao":"Na captação [código], não foi identificado sistema de drenagem eficaz; observaram-se empoçamentos e pontos com risco de infiltração junto à casa de proteção."},{"item":"4.1.2","f":"F1","descricao_F":"","classificacao_appcc":"PPR","desdobramento":"A casa de proteção da captação deve ser mantida em condição higiênico-sanitária satisfatória, livre de infiltrações, rachaduras, fendas e outras alterações.","orientacao_inspetor":"Verifique se a casa de proteção da captação está limpa, sem infiltrações, rachaduras, fendas ou danos estruturais que possam expor a água mineral a contaminações externas.","obs_sim":"A casa de proteção [código] apresentava paredes e pisos íntegros, sem focos de insalubridade e com porta vedada.","nc_nao":"Na casa da captação [código], observou-se borracha de vedação deteriorada na porta, fenda em parede e presença de insetos; registrar os locais e as evidências fotográficas."},{"item":"4.1.2","f":"F2","descricao_F":"","classificacao_appcc":"PPR","desdobramento":"No início da canalização de distribuição da água mineral natural ou da água natural deve ser instalada torneira específica para a coleta de amostras.","orientacao_inspetor":"Verificar existência, localização, conservação e higienização da torneira de coleta no início da canalização; observar a coleta de amostras. Como o plano de amostragem exigido pela Portaria SUVISA nº 4325/2025 prevê análises semanais da água mineral captada, pergunte quais os parâmetros são analisados e a sua periodicidade. Esta informação é importante para entendimento posterior do controle de qualidade realizado pela envasadora.","obs_sim":"Foi localizada e testada torneira específica de amostragem no início da condução da fonte [código], em condições de higienização.","nc_nao":"Na fonte [código], não foi localizada torneira exclusiva de amostragem no início da canalização, conforme inspeção do trajeto [trecho]."},{"item":"4.1.3","f":"F1","descricao_F":"","classificacao_appcc":"PCC","desdobramento":"As edificações, as instalações, a canalização e os equipamentos da captação devem ser submetidos à limpeza e, se for o caso, à desinfecção, de forma a minimizar os riscos de contaminação da água mineral natural e da água natural.","orientacao_inspetor":"1) Solicite informações se na captação é realizado algum procedimento de higienização periódica ou “descontaminação” se necessário e se sim solicite ao responsável a descrição dos serviços realizados (sanitizantes, periodicidade, concentrações, etc.) e depois verifique se eles estão previstos no POP. Descreva essa operação em “Observações Gerais”. 2) Verifique se existe filtro de ar microbiológico no poço (surgência apenas em drenos) e pergunte a periodicidade de troca e peça os registros. 3) Verifique o POP e os registros de limpeza e higienização se existentes na casa de proteção. 4) Para o PPC verifique registros e se existe Condutívimetro em linha ou outra medida complementar para controle da ausência de resíduo de saneante após a higienização, bem como verificação microbiológica ou teste fluorescente / ATP para confirmação se a limpeza e higienização foi satisfatória ou se precisa de reforço com liberação de uso só após este monitoramento. Evidências documentais: POP de higienização da captação, registros dos últimos três meses, capacitação dos executores e registros de troca dos elementos filtrantes, quando existentes.","obs_sim":"A higienização da captação [código] foi descrita no POP [número/revisão] e demonstrada por registros [datas], com saneante, concentração, tempo de contato e liberação compatíveis.","nc_nao":"Na captação [código], o POP previa higienização a cada [frequência], mas os registros demonstraram intervalo de [período] e uso de concentração diversa da prevista, sem justificativa ou avaliação do desvio."},{"item":"4.1.3","f":"F2","descricao_F":"","classificacao_appcc":"PPR","desdobramento":"As operações de limpeza e de desinfecção devem ser realizadas por funcionários comprovadamente capacitados.","orientacao_inspetor":"Conferir certificados e registros de capacitação dos executores da limpeza e desinfecção da captação. Evidências documentais: POP de higienização da captação, registros dos últimos três meses, capacitação dos executores e registros de troca dos elementos filtrantes, quando existentes.","obs_sim":"O executor da higienização da captação [código] foi identificado como [função] e apresentou certificado de capacitação [curso/data/carga horária].","nc_nao":"A pessoa que executava a higienização da captação [código] não correspondia ao profissional indicado no certificado apresentado, sem comprovação de capacitação do executor efetivo."},{"item":"4.1.3","f":"F3","descricao_F":"","classificacao_appcc":"PPR","desdobramento":"Devem ser mantidos registros das operações de limpeza e de desinfecção da captação.","orientacao_inspetor":"Conferir registros datados de limpeza e desinfecção, identificando captação, operação, parâmetros executados e responsável; confrontar com o POP. Evidências documentais: POP de higienização da captação, registros dos últimos três meses, capacitação dos executores e registros de troca dos elementos filtrantes, quando existentes.","obs_sim":"Foram conferidas planilhas de higienização da captação [código], com data, método, produto, concentração e assinatura do executor.","nc_nao":"Foi apresentado POP de higienização da captação, porém não foram apresentados registros assinados que comprovassem sua execução no período [datas]."},{"item":"4.2.2","f":"F1","descricao_F":"","classificacao_appcc":"PPR","desdobramento":"A canalização deve atender ao Regulamento Técnico - Critérios Gerais e Classificação de Materiais para Embalagens e Equipamentos em Contato com Alimentos (RES. RDC 91/01 ou sucessora), outros regulamentos técnicos específicos e suas alterações.","orientacao_inspetor":"Conferir especificações e comprovação de adequação dos materiais da canalização ao contato com alimentos, incluindo conexões e vedações. Solicite a apresentação dos Certificados de Grau Alimentício dos materiais utilizados nas canalizações. Evidências documentais: certificados de grau alimentício dos materiais e conexões da condução e registros de troca de filtros (três meses), quando existentes.","obs_sim":"Os materiais da condução [código] foram identificados por trechos e acompanhados de documentação do fabricante demonstrando adequação ao contato com alimentos.","nc_nao":"Para o trecho [código] da canalização, não foi apresentado certificado de adequação do material ao contato com alimentos; foram observadas conexões improvisadas de materiais distintos."},{"item":"4.2.2","f":"F2","descricao_F":"","classificacao_appcc":"PPR","desdobramento":"As superfícies da canalização que entram em contato com a água mineral natural e com a água natural devem ser lisas, íntegras, impermeáveis, resistentes à corrosão e de fácil higienização.","orientacao_inspetor":"1) Verificar superfícies da canalização, corrosão, fissuras, rugosidades e pontos de difícil higienização; conferir reparos e substituições. 2) Observe se existem vazamentos nas conexões e se as tubulações estão devidamente suportadas, bem como verifique os materiais utilizados e se estão sem corrosão. Evidências documentais: certificados de grau alimentício dos materiais e conexões da condução e registros de troca de filtros (três meses), quando existentes.","obs_sim":"A canalização [código] apresentou superfícies íntegras, conexões sem vazamentos e suportes adequados ao percurso inspecionado.","nc_nao":"Na condução [código], foram vistos pontos com vazamento ativo, amassamento e sustentação improvisada por [material], com dificuldade de higienização."},{"item":"4.2.7","f":"F1","descricao_F":"","classificacao_appcc":"PCC","desdobramento":"A higienização da canalização deve garantir a manutenção das condições higiênico-sanitárias satisfatórias e minimizar o risco de contaminação da água mineral natural e da água natural.","orientacao_inspetor":"Conferir POP, higienização de cada trecho, condições da canalização, tempo/contato/concentração, registros dos últimos três meses, verificação microbiológica e, quando utilizados produtos químicos, demonstração de remoção de resíduos antes da liberação. Verificar filtros e histórico de troca. O não atendimento de requisito classificado como PCC compromete o controle de perigos microbiológicos ou químicos e determina alto risco do processo conforme a regra do Guia.","obs_sim":"Foi comprovada a higienização da condução [código] conforme POP [revisão] e registros [datas], com verificação do resultado e liberação após controle dos perigos pertinentes.","nc_nao":"Na condução [código], os registros de higienização informavam método e frequência diferentes do POP apresentado, sem verificação documentada da eficácia e da liberação do sistema."},{"item":"4.2.7","f":"F2","descricao_F":"","classificacao_appcc":"PPR","desdobramento":"Devem ser mantidos registros das operações de higienização da canalização.","orientacao_inspetor":"Conferir registros de higienização por trecho da canalização, com data, parâmetros executados, responsável e desvios identificados. Evidências documentais: registros de higienização da canalização dos últimos três meses, POP aplicável e capacitação dos executores.","obs_sim":"Os registros da condução [código] identificam datas, agente químico, concentração, operador, tempo de contato e resultado da verificação.","nc_nao":"As planilhas de higienização da condução [código] não identificavam os produtos efetivamente utilizados nem os parâmetros executados; o formulário continha somente data e assinatura."},{"item":"4.2.7","f":"F3","descricao_F":"","classificacao_appcc":"PPR","desdobramento":"A higienização da canalização deve ser realizada por funcionários comprovadamente capacitados.","orientacao_inspetor":"1) Conferir certificados e registros de capacitação dos executores da higienização da canalização; verificar domínio do POP e da resposta aos desvios. 2) Observe se os funcionários responsáveis estão capacitados verificando os registros de higienização, listas de presença, conteúdo, avaliação e certificados de capacitação. Evidências documentais: registros de higienização da canalização dos últimos três meses, POP aplicável e capacitação dos executores.","obs_sim":"O profissional que realizou a higienização da condução [código] apresentou certificado [data] relativo à operação executada.","nc_nao":"O funcionário indicado como executor da higienização da condução [código] não possuía comprovação de capacitação; o certificado apresentado pertencia a outro trabalhador."},{"item":"4.2.8","f":"F1","descricao_F":"","classificacao_appcc":"PPRO","desdobramento":"A higienização deve contemplar, quando aplicável, o desmonte da canalização e prever a frequência de realização desta operação.","orientacao_inspetor":"1) Conferir desmonte e frequência no POP, execução, registros e remontagem higiênica. 2) Solicite os registros dos serviços de desmontagem, passivação e desincrustação da canalização realizados nos últimos anos, bem como verifique se esta operação de desmontagem, mesmo se relatado que não é necessário, está descrita no POP de higienização e se também existe nele as ações corretivas necessárias. Evidências documentais: registros de desmontagem, passivação, desincrustação e ações corretivas conforme necessidade e frequência definida.\nDestaca-se que devido à natureza do produto pode ocorrer a formação de biofilme junto a superfícies rugosas, como conexões internas e junto às juntas utilizadas.","obs_sim":"Foi apresentado registro de desmontagem e limpeza da condução [código], incluindo [válvulas/conexões/filtros], conforme condição definida no POP.","nc_nao":"Não foram apresentados registros de desmonte da condução [código], troca de vedações ou desincrustação, apesar de previsão de manutenção no procedimento."},{"item":"4.2.8","f":"F2","descricao_F":"","classificacao_appcc":"PPRO","desdobramento":"Caso seja constatada a presença de incrustações e de outras alterações que possam comprometer a qualidade higiênico-sanitária da água mineral natural e da água natural, devem ser revistas as operações de higienização e adotadas as medidas corretivas necessárias.","orientacao_inspetor":"1) Verificar incrustações, bloqueio do circuito e correções; conferir revisão da higienização, avaliação da água afetada e nova liberação. 2) Verifique se há incrustações ou alterações estruturais na captação ou tubulações. Caso sejam constatadas, certifique-se de que os procedimentos de higienização foram reavaliados e as ações corretivas foram implementadas imediatamente. Evidências documentais: registros de desmontagem, passivação, desincrustação e ações corretivas conforme necessidade e frequência definida.","obs_sim":"O histórico de inspeção da condução [código] registrou ocorrência de [incrustação/alteração], ação corretiva, nova verificação e liberação.","nc_nao":"Após constatação de incrustações na canalização [código], não foram demonstradas revisão da higienização e medidas corretivas com verificação de eficácia."},{"item":"4.2.9","f":"F1","descricao_F":"","classificacao_appcc":"POP","desdobramento":"Devem ser implementados Procedimentos Operacionais Padronizados-POP referentes às operações de higienização da canalização.","orientacao_inspetor":"Conferir POP implantado para o circuito, parâmetros, registros, critérios e responsável pela liberação e resposta aos desvios. Evidências documentais: POP de higienização da canalização, versão vigente, acesso pelos executores e parâmetros técnicos previstos.","obs_sim":"O POP [número/revisão] de higienização da condução [código] estava implantado, com frequência, método e agentes coerentes com os registros.","nc_nao":"Embora apresentado o POP [número], as operações efetivamente registradas na condução [código] divergiam quanto ao agente químico e à frequência descritos no procedimento."},{"item":"4.2.9","f":"F2","descricao_F":"","classificacao_appcc":"POP","desdobramento":"Os POP devem conter informações sobre: natureza da superfície a ser higienizada, métodos de higienização, princípios ativos utilizados e sua concentração, tempo de contato dos agentes químicos e ou físicos utilizados na operação de higienização, temperatura, frequência e outras informações que se fizerem necessárias.","orientacao_inspetor":"Conferir superfícies, métodos, princípios ativos, concentrações, tempo, temperatura e frequência no POP; verificar compatibilidade com os produtos e equipamentos utilizados. Evidências documentais: POP de higienização da canalização, versão vigente, acesso pelos executores e parâmetros técnicos previstos.","obs_sim":"O POP [código] descreve material da superfície, método, concentração, contato, temperatura quando aplicável e frequência de higienização.","nc_nao":"O POP de higienização da condução [código] não define [concentração/tempo de contato/periodicidade] do saneante e não estabelece critérios para desmontagem quando aplicável."},{"item":"4.3.2","f":"F1","descricao_F":"","classificacao_appcc":"PPR","desdobramento":"O reservatório deve atender ao Regulamento Técnico - Critérios Gerais e Classificação de Materiais para Embalagens e Equipamentos em Contato com Alimentos? (RES. RDC 91/01 ou sucessora), outros regulamentos técnicos específicos e suas alterações.","orientacao_inspetor":"1) Conferir especificações e comprovação de adequação dos materiais do reservatório e acessórios ao contato com alimentos. 2) Solicite a apresentação dos Certificados de Grau Alimentício dos materiais utilizados nos reservatórios, e verifique os certificados dos materiais apresentados. Evidências documentais: certificados de grau alimentício dos materiais do reservatório, identificação do tanque e registros de conservação.","obs_sim":"O reservatório [código] de material [identificação] apresentou certificado de adequação ao contato com alimentos [referência].","nc_nao":"Não foi apresentado documento de adequação do material do reservatório [código] ao contato com alimentos, embora solicitado durante a inspeção."},{"item":"4.3.2","f":"F2","descricao_F":"","classificacao_appcc":"PPR","desdobramento":"As superfícies que entram em contato com a água mineral natural ou com a água natural devem ser lisas, íntegras, impermeáveis, resistentes à corrosão e de fácil higienização.","orientacao_inspetor":"1) Verificar superfícies internas, corrosão, fissuras, revestimentos e facilidade de higienização; conferir registros de manutenção.  Evidências documentais: certificados de grau alimentício dos materiais do reservatório, identificação do tanque e registros de conservação.","obs_sim":"No reservatório [código], as superfícies e conexões observadas estavam conservadas, sem corrosão, vazamento ou danos.","nc_nao":"No reservatório [código], foi identificado vazamento na saída [local], além de ponto de oxidação, comprometendo a integridade do conjunto."},{"item":"4.3.2","f":"F3","descricao_F":"","classificacao_appcc":"PPR","desdobramento":"As superfícies que entram em contato com a água mineral natural ou com a água natural devem estar em adequado estado de conservação, livres de vazamentos e permitir a inspeção interna.","orientacao_inspetor":"1) Verificar superfícies externas, corrosão, fissuras, revestimentos e facilidade de higienização; conferir registros de manutenção. 2) Observe se existem vazamentos nas conexões Evidências documentais: certificados de grau alimentício dos materiais do reservatório, identificação do tanque e registros de conservação.","obs_sim":"Superfícies internas acessíveis íntegras, lisas e higienizáveis, sem corrosão ou fissuras observadas.","nc_nao":"Reservatório apresenta vazamentos nas conexões com corrosão ou fissuras."},{"item":"4.3.3","f":"F1","descricao_F":"Dispositivos do reservatório","classificacao_appcc":"PPRO","desdobramento":"critérios selecionáveis abaixo","orientacao_inspetor":"\n1) Verificar extravasor e tela milimetrada: integridade, proteção, funcionamento e correção das falhas.\n2) Verificar dispositivo de esvaziamento inferior, drenagem completa, conservação e condições de uso.\n3) Conferir especificação dos filtros, critérios e frequência de verificação e troca; verificar registros, integridade e providências após falhas.\n4) Verificar filtro de ar microbiológico: especificação de retenção, instalação, integridade e proteção contra entrada de contaminantes.\n5) Verificar válvula de retenção ou fecho hídrico: instalação, funcionamento, proteção contra retorno, inspeções e correção das falhas.\n6) Verificar torneira específica de amostragem, localização, identificação, conservação, higienização e condições de coleta representativa. Evidências documentais: especificação, instalação e manutenção de extravasor, filtro microbiológico, válvula/sifão, drenagem e torneira; registros de troca dos elementos filtrantes (três meses).","obs_sim":"No reservatório [código], foram verificados extravasor protegido, filtro microbiológico, dreno inferior, válvula/sifão e torneira de amostragem, com manutenção documentada dos filtros.","nc_nao":"No reservatório [código], foi constatada [ausência de filtro microbiológico no respiro/falta de registro de troca/ligação indevida do extravasor], conforme [registro fotográfico e documento]."},{"item":"4.3.4","f":"F1","descricao_F":"","classificacao_appcc":"PC","desdobramento":"A inspeção visual do reservatório deve ser efetuada na frequência definida pelo estabelecimento industrial.","orientacao_inspetor":"1) Conferir frequência e registros da inspeção visual interna, identificação do reservatório e achados; observar condições internas e encaminhamento dos desvios. 2) Verifique no POP a previsão e descrição da inspeção visual, bem como solicite os registros das visitas e ações corretivas. Relate como NC se não houver previsão de visita e/ou se não existirem registros que comprovem as aberturas e a necessidade ou não de ações corretivas. Nestes registros é vital a apresentação de relatórios com fotos do seu interior. 3) Também verifique se existe “porta de visita” para inspeção interna. Evidências documentais: POP e registros datados de inspeção visual interna dos reservatórios, inclusive achados e providências no período de referência de um ano.","obs_sim":"A inspeção visual do reservatório [código] foi registrada em [data], com descrição das superfícies e ausência de incrustações.","nc_nao":"O POP prevê inspeção visual periódica do reservatório [código], mas não foram apresentados os registros do período [datas]."},{"item":"4.3.4","f":"F2","descricao_F":"","classificacao_appcc":"PPRO","desdobramento":"Caso seja constatada a presença de incrustações e de outras alterações que possam comprometer a qualidade higiênico-sanitária da água mineral natural e da água natural devem ser revistas as operações de higienização e adotadas as medidas corretivas necessárias.","orientacao_inspetor":"1) Verificar incrustações e alterações; conferir bloqueio, revisão da higienização, correções e nova liberação do reservatório. 2) verifique conexões do reservatório com sistemas reuso ou serviço. Evidências documentais: POP e registros datados de inspeção visual interna dos reservatórios, inclusive achados e providências no período de referência de um ano.","obs_sim":"A não conformidade observada em [data] no reservatório [código] originou registro de manutenção, correção e verificação antes da liberação.","nc_nao":"Havia registro de manutenção corretiva do reservatório [código], mas não foram apresentados registros da manutenção preventiva prevista no POP nem avaliação da eficácia."},{"item":"4.3.5","f":"F1","descricao_F":"","classificacao_appcc":"PCC","desdobramento":"A higienização do reservatório deve ser realizada de forma que garanta a manutenção das condições higiênico-sanitárias satisfatórias e minimize o risco de contaminação da água mineral natural e da água natural.","orientacao_inspetor":"Conferir POP, registros dos últimos três meses, concentrações e tempo de contato dos produtos, inspeção pós-higienização, resultados de verificação microbiológica e demonstração de ausência de resíduos químicos quando se empregarem saneantes/detergentes. Conferir monitoramento e responsável pela liberação do reservatório. Para PCC não atendido, classificar o processo alto risco em razão do perigo microbiológico e/ou químico não controlado.","obs_sim":"A higienização do reservatório [código] foi executada em [data] com método [CIP/limpeza], tempo de contato e verificação da eficácia documentados.","nc_nao":"A higienização efetiva do reservatório [código] foi informada como realizada a cada [intervalo], enquanto os registros indicavam [intervalo diferente]; não foi comprovada a execução compatível com o POP."},{"item":"4.3.5","f":"F2","descricao_F":"","classificacao_appcc":"PPR","desdobramento":"Devem ser mantidos registros das operações de higienização do reservatório.","orientacao_inspetor":"Conferir registros por reservatório, com data, parâmetros executados, responsável e desvios; confrontar com o POP. Evidências documentais: registros individualizados de higienização dos reservatórios dos últimos três meses e capacitação dos executores; controle de liberação pós-higienização.","obs_sim":"Os registros por reservatório [código] estavam individualizados, datados e assinados, incluindo solução, concentração, contato e liberação.","nc_nao":"Os registros de higienização dos reservatórios [códigos] repetiam data e periodicidade não confirmadas pela operação relatada; registrar a divergência verificada."},{"item":"4.3.5","f":"F3","descricao_F":"","classificacao_appcc":"PPR","desdobramento":"A higienização do reservatório deve ser realizada por funcionários comprovadamente capacitados.","orientacao_inspetor":"Conferir certificados e registros de capacitação dos executores da higienização dos reservatórios; verificar domínio do POP e da resposta aos desvios. Evidências documentais: registros individualizados de higienização dos reservatórios dos últimos três meses e capacitação dos executores; controle de liberação pós-higienização.","obs_sim":"Os profissionais responsáveis pela higienização dos reservatórios apresentaram certificados [datas e conteúdos] compatíveis com as atividades.","nc_nao":"O executor da higienização do reservatório [código] não apresentou certificado de capacitação referente ao procedimento utilizado."},{"item":"4.3.6","f":"F1","descricao_F":"","classificacao_appcc":"POP","desdobramento":"Devem ser implementados Procedimentos Operacionais Padronizados-POP referentes às operações de higienização do reservatório.","orientacao_inspetor":"Conferir métodos, concentração, contato, temperatura e frequência no POP; verificar amostragem, critérios e responsável pela liberação do reservatório. Evidências documentais: POP de higienização dos reservatórios com concentrações, tempos, método, frequência, temperatura quando aplicável e critérios de liberação.","obs_sim":"Foi apresentado POP vigente e efetivamente implantado para higienização do reservatório [código], com registros coerentes.","nc_nao":"Não foi comprovada a implantação do POP de higienização do reservatório [código]; o procedimento estava arquivado sem registros correspondentes à operação."},{"item":"4.3.6","f":"F2","descricao_F":"","classificacao_appcc":"POP","desdobramento":"O Procedimento Operacional Padronizado referente à higienização do reservatório deve estar disponível e atualizado.","orientacao_inspetor":"Verificar versão atualizada do POP de higienização do reservatório e sua disponibilidade aos executores no local de trabalho. Evidências documentais: POP de higienização dos reservatórios com concentrações, tempos, método, frequência, temperatura quando aplicável e critérios de liberação.","obs_sim":"O POP de higienização do reservatório [código] estava disponível para consulta no local [identificação].","nc_nao":"O POP [código] não estava disponível em [local], conforme verificado durante a inspeção."},{"item":"4.3.6","f":"F3","descricao_F":"","classificacao_appcc":"POP","desdobramento":"Os POP devem conter informações sobre: natureza da superfície a ser higienizada, métodos de higienização, princípios ativos dos agentes químicos utilizados e sua concentração, tempo de contato dos agentes químicos e ou físicos utilizados na operação de higienização, temperatura, frequência e outras informações que se fizerem necessárias.","orientacao_inspetor":"Conferir métodos, concentração, contato, temperatura e frequência no POP; verificar amostragem, critérios e responsável pela liberação do reservatório. Evidências documentais: POP de higienização dos reservatórios com concentrações, tempos, método, frequência, temperatura quando aplicável e critérios de liberação.","obs_sim":"O POP [número] descreve os parâmetros de limpeza e desinfecção e define critérios para liberação do reservatório [código].","nc_nao":"O POP do reservatório [código] não apresenta a concentração do saneante, o tempo de contato ou a frequência praticada nos registros."},{"item":"4.5.2","f":"F1","descricao_F":"","classificacao_appcc":"PPR","desdobramento":"A recepção das embalagens retornáveis para um novo ciclo de uso deve ser efetuada em área distinta da recepção dos demais insumos para evitar contaminação cruzada.","orientacao_inspetor":"Verificar separação da recepção de retornáveis em relação aos demais insumos e observar fluxos, armazenamento e possibilidade de contaminação cruzada.","obs_sim":"Na recepção, os garrafões retornáveis são recebidos em [área identificada], separada dos demais insumos, com fluxo que evita contaminação cruzada.","nc_nao":"Os garrafões retornáveis eram recebidos no mesmo ambiente e simultaneamente aos demais insumos, sem separação de fluxos ou medidas demonstradas de prevenção de contaminação cruzada."},{"item":"4.5.3","f":"F1","descricao_F":"","classificacao_appcc":"PC","desdobramento":"Os insumos devem ser submetidos à inspeção no ato da recepção.","orientacao_inspetor":"Observar inspeção no recebimento; conferir especificações, integridade, identificação, validade e registros de aceitação dos insumos. Evidências documentais: registros de recebimento e inspeção; notas fiscais recentes de embalagens, tampas, rótulos e saneantes; fichas técnicas, regularização de saneantes e laudos de migração pertinentes.","obs_sim":"A recepção de [embalagens/rótulos/saneantes] do lote [código] foi registrada em [data], com conferência de integridade, identidade, especificação e validade.","nc_nao":"Na recepção de [insumo], havia apenas ficha de controle de estoque, sem registro de inspeção do lote e sem critérios de aceitação e rejeição."},{"item":"4.5.3","f":"F2","descricao_F":"","classificacao_appcc":"PPRO","desdobramento":"Quando as especificações previamente determinadas não forem atendidas, os insumos devem ser reprovados.","orientacao_inspetor":"Conferir critérios sanitários de reprovação e registros; verificar bloqueio dos insumos não conformes e prevenção de seu uso na produção. Evidências documentais: registros de recebimento e inspeção; notas fiscais recentes de embalagens, tampas, rótulos e saneantes; fichas técnicas, regularização de saneantes e laudos de migração pertinentes.","obs_sim":"O lote [código] de [insumo] foi reprovado por [desvio], segregado e registrado conforme procedimento [código].","nc_nao":"Foram encontrados saneantes vencidos em área de uso e não havia documentação da reprovação e segregação dos lotes."},{"item":"4.5.3","f":"F3","descricao_F":"","classificacao_appcc":"PPR","desdobramento":"Os produtos saneantes devem estar regularizados no órgão competente.","orientacao_inspetor":"Conferir regularização dos saneantes (ANVISA), indicação de uso, rotulagem e validade; verificar compatibilidade dos produtos com a finalidade declarada. Evidências documentais: registros de recebimento e inspeção; notas fiscais recentes de embalagens, tampas, rótulos e saneantes; fichas técnicas, regularização de saneantes e laudos de migração pertinentes.","obs_sim":"O saneante [nome/apresentação/lote] tinha regularização compatível com seu uso pretendido, rótulo íntegro e validade vigente.","nc_nao":"Foi encontrado produto químico destinado exclusivamente à fabricação de saneantes sendo utilizado como desinfetante, sem comprovação de regularização para essa finalidade."},{"item":"4.5.4","f":"F1","descricao_F":"","classificacao_appcc":"PPRO","desdobramento":"As embalagens plásticas retornáveis recebidas para um novo ciclo de uso devem ser avaliadas individualmente quanto à aparência interna e externa, à presença de resíduos e ao odor.","orientacao_inspetor":"Observar avaliação interna, externa e de odor de cada retornável; conferir critérios de aceitação, iluminação, responsáveis, registros e eficácia da seleção.","obs_sim":"Na triagem, os garrafões recebidos foram inspecionados individualmente quanto a odor, integridade, cor, resíduos e superfície externa.","nc_nao":"Foi observado recebimento de garrafões sem inspeção individual de odor, resíduos internos e estado do gargalo, apesar da etapa prevista no POP."},{"item":"4.5.4","f":"F2","descricao_F":"","classificacao_appcc":"PPRO","desdobramento":"As embalagens plásticas com amassamentos, rachaduras, ranhuras, remendos, deformações internas e externas do gargalo, com alterações de odor e cor, dentre outras alterações que possam comprometer a qualidade higiênico-sanitária da água mineral natural ou da água natural devem ser reprovadas.","orientacao_inspetor":"Verificar rejeição de embalagens com danos, resíduos ou alterações de odor e cor; conferir critérios, segregação, registros e impedimento de retorno ao uso.","obs_sim":"Os garrafões foram avaliados individualmente no recebimento; os que apresentavam [defeito] foram segregados.","nc_nao":"No recebimento, foi observado garrafão com [defeito] sem segregação, em [local]."},{"item":"4.5.6","f":"F1","descricao_F":"","classificacao_appcc":"PPRO","desdobramento":"Os insumos reprovados na recepção devem ser imediatamente devolvidos ao fornecedor ou distribuidor e, quando não for possível, devem ser devidamente identificados e armazenados separadamente até o seu destino final.","orientacao_inspetor":"Verificar devolução imediata ou identificação e segregação dos reprovados; conferir bloqueio, controle de acesso e rastreabilidade até o destino final. Evidências documentais: registros de segregação, reprovação e destino de garrafões, garrafas, tampas ou outros insumos, com identificação de lote.","obs_sim":"O insumo reprovado [lote] estava segregado e identificado, com registro da devolução ou destinação [data/responsável].","nc_nao":"Os garrafões reprovados foram devolvidos aos transportadores sem registros que identificassem data, quantidade, responsável e destino."},{"item":"4.5.6","f":"F2","descricao_F":"","classificacao_appcc":"PPR","desdobramento":"O destino final dos insumos reprovados deve ser registrado em documento datado e assinado pelo funcionário responsável.","orientacao_inspetor":"Conferir documento de destinação dos insumos reprovados, com identificação, quantidade, data, destino e assinatura do responsável. Evidências documentais: registros de segregação, reprovação e destino de garrafões, garrafas, tampas ou outros insumos, com identificação de lote.","obs_sim":"O destino do insumo reprovado [lote] foi documentado em [formulário], datado e assinado.","nc_nao":"A empresa informou devolver insumos reprovados, mas não apresentou documento de devolução ou destinação final assinado pelo responsável."},{"item":"4.5.8","f":"F1","descricao_F":"","classificacao_appcc":"POP","desdobramento":"Devem ser implementados Procedimentos Operacionais Padronizados - POP referentes à operação de recepção das embalagens.","orientacao_inspetor":"Conferir POP de recepção implantado, com inspeção individual, critérios de aceitação e reprovação; comparar com a prática observada. Evidências documentais: POP de recepção de embalagens, registros de inspeção, critério de rejeição e destino dos materiais reprovados.","obs_sim":"O POP [número/revisão] de recepção de embalagens estava disponível, com instruções de inspeção, aceitação e reprovação aplicadas na operação.","nc_nao":"O POP de recepção apresentado não contemplava a inspeção individual das embalagens e não correspondia à triagem observada."},{"item":"4.5.8","f":"F2","descricao_F":"","classificacao_appcc":"POP","desdobramento":"Os POP referentes à recepção das embalagens devem conter informações sobre o destino final das embalagens reprovadas e outras informações que se fizerem necessárias.","orientacao_inspetor":"Conferir no POP identificação, segregação, devolução ou destinação das embalagens reprovadas e os registros correspondentes. Evidências documentais: POP de recepção de embalagens, registros de inspeção, critério de rejeição e destino dos materiais reprovados.","obs_sim":"O POP [número] especifica segregação, devolução ou destinação final de embalagens e rótulos reprovados, com rastreabilidade.","nc_nao":"O POP de recepção das embalagens e rótulos não indicava o destino final dos materiais reprovados, embora existisse prática informal de devolução."},{"item":"4.5.8","f":"F3","descricao_F":"","classificacao_appcc":"POP","desdobramento":"Os Procedimentos Operacionais Padronizados - POP referentes à operação de recepção das embalagens devem conter informações sobre inspeção individual, aceitação e reprovação de embalagens.","orientacao_inspetor":"Conferir POP de recepção implantado, com inspeção individual, critérios de aceitação e reprovação; comparar com a prática observada. Evidências documentais: POP de recepção de embalagens, registros de inspeção, critério de rejeição e destino dos materiais reprovados.","obs_sim":"POP de recepção implantado, incluindo inspeção individual, critérios de aceitação e reprovação de embalagens.","nc_nao":"Não existe POP implantado para recepção e triagem das embalagens retornáveis."},{"item":"4.6.3","f":"F1","descricao_F":"","classificacao_appcc":"PCC","desdobramento":"As embalagens de primeiro uso, quando não fabricadas no próprio estabelecimento industrial, devem ser submetidas ao enxágue em maquinário automático, utilizando-se solução desinfetante, exceto as embalagens descartáveis do tipo copo.","orientacao_inspetor":"Conferir validação, limites críticos de concentração, contato e temperatura aplicáveis; verificar bicos, monitoramento (limites críticos - medidores ou sensores) e registros; bloquear e avaliar embalagens e produto afetados no desvio.","obs_sim":"As embalagens descartáveis de primeiro uso [tipo] foram submetidas à etapa automática prevista, com registros [data/linha], exceto copos quando aplicável.","nc_nao":"Na linha [código], não foi demonstrada etapa de enxágue automático com solução desinfetante para embalagens de primeiro uso não enquadradas na exceção dos copos."},{"item":"4.6.4","f":"F1","descricao_F":"Pré-lavagem","classificacao_appcc":"POP","desdobramento":"As embalagens retornadas para um novo ciclo de uso, antes da etapa de higienização automática, devem ser submetidas à pré-lavagem para a remoção do rótulo, dos resíduos da substância adesiva e das sujidades das superfícies interna e externa.","orientacao_inspetor":"Observar remoção de rótulos, adesivos e sujidades internas e externas; conferir método, frequência e correção de falhas da pré-lavagem.","obs_sim":"No pré-tratamento, foi observada a remoção dos rótulos, adesivo e sujidades internas e externas dos garrafões antes da lavadora automática.","nc_nao":"Na alimentação da lavadora, foram observados garrafões com resíduos de adesivo e sujidades internas remanescentes da pré-lavagem."},{"item":"4.6.5","f":"F1","descricao_F":"","classificacao_appcc":"PPRO","desdobramento":"As embalagens retornadas para um novo ciclo de uso devem ser submetidas à limpeza em maquinário automático.","orientacao_inspetor":"Verificar limpeza automática, funcionamento dos bicos e parâmetros da lavadora; conferir critérios de ação, registros e correções antes da desinfecção. Evidências documentais: qualificação/validação das condições de operação da lavadora automática; dados de concentração, temperatura, pressão, contato e registros dos desvios.","obs_sim":"A lavadora automática operava com jatos ativos em todos os bicos de limpeza e parâmetros verificados em [data].","nc_nao":"Durante operação da lavadora [linha], alguns bicos do primeiro estágio não injetavam a solução de limpeza; registrar posições e providências adotadas."},{"item":"4.6.5","f":"F2","descricao_F":"","classificacao_appcc":"PCC","desdobramento":"As embalagens retornadas para um novo ciclo de uso devem ser submetidas à desinfecção em maquinário automático.","orientacao_inspetor":"Conferir eficácia validada (relatório conforme ABNT NBR 14637:2011, quando aplicável), concentração, contato, temperatura e velocidade da lavadora; verificar bicos, pressão dos jatos, registros, bloqueio e destino das embalagens e do produto afetados. Evidências documentais: qualificação/validação das condições de operação da lavadora automática; dados de concentração, temperatura, pressão, contato e registros dos desvios.","obs_sim":"A desinfecção foi realizada conforme validação [relatório/data], com produto, concentração, contato e temperatura compatíveis com a rotina monitorada.","nc_nao":"O relatório de eficácia da lavadora [linha] utilizava outro saneante ou concentração diferente da praticada, sem validação atualizada; foram identificados bicos com funcionamento inadequado."},{"item":"4.6.6","f":"F1","descricao_F":"","classificacao_appcc":"PCC","desdobramento":"O enxágue das embalagens retornadas para um novo ciclo de uso deve garantir a eliminação dos resíduos dos produtos químicos utilizados na higienização.","orientacao_inspetor":"Conferir limite para cada resíduo, eficácia e sensibilidade do teste; verificar frequência, registros, bloqueio do produto afetado e liberação após correção. Evidências documentais: registros dos testes indicadores de ausência de resíduos químicos em retornáveis, frequência, limites, resultado e bloqueio em caso de falha.","obs_sim":"O enxágue final foi conferido com teste indicador definido no POP [código], com resultado de ausência de resíduos do saneante nos horários amostrados.","nc_nao":"Não foi comprovada a eliminação de resíduos de saneantes após o enxágue das embalagens retornáveis, pois não foram realizados os testes indicadores definidos no procedimento."},{"item":"4.6.6","f":"F2","descricao_F":"","classificacao_appcc":"PC","desdobramento":"A ausência desses resíduos deve ser comprovada por testes indicadores.","orientacao_inspetor":"Conferir registros de testes indicadores por lote ou condição de operação, método, limites de aceitação, produto químico monitorado, frequência, resultado, ações diante de teste positivo e bloqueio de embalagens sem comprovação de ausência de resíduos.","obs_sim":"Foram apresentados registros dos testes de arraste [datas/horários] e frascos de indicadores dentro da validade.","nc_nao":"Os registros dos testes indicadores apresentavam horários sem preenchimento e foram encontrados frascos de reagente indicador com validade expirada."},{"item":"4.6.7","f":"F1","descricao_F":"","classificacao_appcc":"PPRO","desdobramento":"O enxágue final das embalagens retornadas para um novo ciclo de uso e daquelas de primeiro uso deve ser feito com a água mineral natural ou com a água natural a ser envasada, exceto as embalagens descartáveis do tipo copo.","orientacao_inspetor":"Conferir origem, qualidade da água e bicos do enxágue. Nos descartáveis soprados na unidade, verificar filtro microbiológico final do ar, integridade, manutenção e microbiologia no ponto de uso.","obs_sim":"No(a) [local/linha/equipamento], foi comprovado o atendimento a enxágue final das embalagens retornadas para um novo ciclo de uso e daquelas de primeiro uso deve ser feito com a água mineral natural ou com a água natural a ser envasada, exceto as embalagens d, por [verificação realizada/documento e data].","nc_nao":"Na lavadora automática da linha [identificação], os bicos de enxágue estavam obstruídos e o jato de água não alcançava o fundo das embalagens."},{"item":"4.6.8","f":"F1","descricao_F":"","classificacao_appcc":"PCC","desdobramento":"As tampas das embalagens não devem ser veículos de contaminação da água mineral natural e da água natural.","orientacao_inspetor":"Verificar proteção e higienização das tampas, eficácia validada e limites críticos do processo; conferir monitoramento operacional e microbiológico, rastreabilidade, registros, bloqueio e destino dos lotes com falhas. Quando houver ozônio, verificar parâmetros do processo e controle da exposição ambiental.","obs_sim":"As tampas do lote [identificação] permaneceram protegidas até o uso e havia documentação de higienização do fornecedor [laudo/lote].","nc_nao":"Após abertura das embalagens secundárias, as tampas ficaram expostas fora da sala de envase e não foi apresentada comprovação de higienização ou proteção adequada."},{"item":"4.6.9","f":"F1","descricao_F":"","classificacao_appcc":"PPR","desdobramento":"A saída do equipamento de higienização das embalagens deve estar posicionada próxima à sala de envase para evitar que as embalagens circulem em ambiente aberto. Quando não for possível, as esteiras devem ser protegidas por cobertura.","orientacao_inspetor":"Verificar proximidade da saída da lavadora com a sala de envase e proteção das esteiras contra exposição das embalagens ao ambiente aberto.","obs_sim":"A transferência das embalagens higienizadas à sala de envase ocorreu imediatamente por esteira automática, sem exposição a ambiente aberto.","nc_nao":"Foram observadas embalagens higienizadas aguardando transferência em ambiente aberto, com risco de recontaminação."},{"item":"4.6.9","f":"F2","descricao_F":"","classificacao_appcc":"PPRO","desdobramento":"O transporte das embalagens da área de higienização para a sala de envase deve ser realizado imediatamente.","orientacao_inspetor":"Observar transporte imediato ao envase; conferir critérios de espera, tratamento de paradas, proteção das embalagens e re-higienização quando necessária.","obs_sim":"No(a) [local/linha/equipamento], foi comprovado o atendimento a transporte das embalagens da área de higienização para a sala de envase deve ser realizado imediatamente, por [verificação realizada/documento e data].","nc_nao":"No(a) [local/linha/equipamento], constatou-se ausência ou falha de transporte das embalagens da área de higienização para a sala de envase deve ser realizado imediatamente. Evidência: [fato constatado, data e identificação]."},{"item":"4.6.10","f":"F1","descricao_F":"","classificacao_appcc":"PPR","desdobramento":"A passagem das embalagens da área de higienização para a sala de envase deve ser feita por meio de abertura destinada exclusivamente para este fim.","orientacao_inspetor":"Verificar abertura exclusiva para embalagens, dimensões compatíveis com a passagem. Verificar o uso de lâmpadas UV e se existe manutenção, limpeza, higienização e monitoramento microbiológico e registro de troca delas.","obs_sim":"A abertura para passagem das embalagens é exclusiva, dimensionada e utilizada pela esteira da linha [código].","nc_nao":"Na passagem entre a lavadora e a sala de envase [linha] foi observada abertura sem delimitação ou barreira física adequada."},{"item":"4.6.10","f":"F2","descricao_F":"","classificacao_appcc":"PPRO","desdobramento":"Não é permitido o transporte manual das embalagens da área de higienização para a sala de envase.","orientacao_inspetor":"Observar se as embalagens passam da área de higienização à sala de envase sem transporte manual.","obs_sim":"Durante a inspeção da linha [código], não houve transporte manual das embalagens higienizadas para a sala de envase.","nc_nao":"Na transferência da linha [código], as embalagens higienizadas foram levadas manualmente entre ambientes em [momento/local]."},{"item":"4.6.10","f":"F3","descricao_F":"","classificacao_appcc":"PPRO","desdobramento":"Essa abertura deve ser dimensionada somente para permitir a passagem das embalagens e permanecer fechada durante a paralisação do processo de envase.","orientacao_inspetor":"Observar ausência de transporte manual e fechamento da passagem nas paradas; conferir procedimento, monitoramento.","obs_sim":"A passagem da linha [código] estava dimensionada para a embalagem e foi fechada durante a interrupção do envase, conforme teste in loco.","nc_nao":"Na paralisação da linha [código], a abertura de passagem permaneceu aberta, sem guilhotina ou outro mecanismo de fechamento; identificar o ponto."},{"item":"4.6.11","f":"F1","descricao_F":"","classificacao_appcc":"POP","desdobramento":"As operações de limpeza e desinfecção das embalagens devem seguir procedimentos que assegurem condições higiênico-sanitárias satisfatórias.","orientacao_inspetor":"Conferir procedimentos de limpeza e desinfecção das embalagens e sua execução; verificar coerência com os controles específicos da lavadora e do enxágue. Evidências documentais: registros de capacitação e de higienização de embalagens retornáveis, e declaração do fabricante quanto à sanitização das tampas quando aplicável.","obs_sim":"A higienização das embalagens foi acompanhada durante a operação, e os trabalhadores seguiram o POP [código] nos parâmetros verificados.","nc_nao":"Os executores da higienização utilizavam procedimento diferente do POP [código], sem registro da alteração ou avaliação do desvio."},{"item":"4.6.11","f":"F2","descricao_F":"","classificacao_appcc":"PPR","desdobramento":"As operações de limpeza e desinfecção das embalagens devem ser realizadas por funcionários comprovadamente capacitados.","orientacao_inspetor":"Conferir os certificados de capacitação dos funcionários na limpeza e desinfecção das embalagens e observar seu domínio dos procedimentos e da resposta a falhas. Evidências documentais: registros de capacitação e de higienização de embalagens retornáveis, e declaração do fabricante quanto à sanitização das tampas quando aplicável.","obs_sim":"No(a) [local/linha/equipamento], foi comprovado o atendimento a operações de limpeza e desinfecção das embalagens devem ser realizadas por funcionários comprovadamente capacitados, por [verificação realizada/documento e data].","nc_nao":"Não foi apresentada comprovação documental de operações de limpeza e desinfecção das embalagens devem ser realizadas por funcionários comprovadamente capacitados para [pessoa, equipamento ou lote], solicitada durante a inspeção."},{"item":"4.6.12","f":"F1","descricao_F":"","classificacao_appcc":"POP","desdobramento":"Devem ser implementados Procedimentos Operacionais Padronizados-POP referentes às operações de higienização das embalagens.","orientacao_inspetor":"Conferir no POP superfícies, métodos, princípios ativos, concentrações, tempo e temperatura; comparar com os parâmetros executados na linha. Evidências documentais: POP vigente de higienização das embalagens; registros, qualificação da lavadora e declarações pertinentes às tampas.","obs_sim":"O POP [código] foi observado em execução na lavadora [linha], com registros de parâmetros e inspeção da higienização.","nc_nao":"Foi apresentado POP de higienização, mas as planilhas de monitoramento estavam em branco e não havia comprovação da implantação na linha [código]."},{"item":"4.6.12","f":"F2","descricao_F":"","classificacao_appcc":"POP","desdobramento":"Os Procedimentos Operacionais Padronizados referentes às operações de higienização das embalagens devem estar disponíveis e atualizados.","orientacao_inspetor":"Verificar se o POP de higienização de embalagens está disponível no local de execução e atualizado. Evidências documentais: POP vigente de higienização das embalagens; registros, qualificação da lavadora e declarações pertinentes às tampas.","obs_sim":"O POP [identificação e revisão] estava atualizado e disponível para consulta na linha [identificação].","nc_nao":"O POP de higienização de embalagens não estava disponível ou estava desatualizado na linha [identificação]."},{"item":"4.6.12","f":"F3","descricao_F":"","classificacao_appcc":"POP","desdobramento":"Os POP devem conter informações sobre: natureza da superfície a ser higienizada, métodos de higienização, princípios ativos utilizados e sua concentração, tempo de contato dos agentes químicos e ou físicos utilizados na operação de higienização, temperatura e outras informações que se fizerem necessárias.","orientacao_inspetor":"Conferir no POP superfícies, métodos, princípios ativos, concentrações, tempo e temperatura; comparar com os parâmetros executados na linha. Evidências documentais: POP vigente de higienização das embalagens; registros, qualificação da lavadora e declarações pertinentes às tampas.","obs_sim":"O POP [código] descrevia o saneante, sua concentração, o tempo de contato, os enxágues e a forma de teste indicador.","nc_nao":"No POP de higienização de garrafões [código], não constavam a concentração do produto, o tempo de contato ou o teste indicador praticado na linha."},{"item":"4.7.1","f":"F1","descricao_F":"","classificacao_appcc":"PPR","desdobramento":"O envase e o fechamento das embalagens devem ser realizados por equipamentos automáticos.","orientacao_inspetor":"Verificar envase e fechamento automáticos, integridade dos equipamentos e ausência de intervenções manuais incompatíveis com a operação.","obs_sim":"O envase e o fechamento da linha [código] foram realizados por equipamentos automáticos, sem intervenção manual na área de produto exposto.","nc_nao":"Na linha [código], foi necessária intervenção manual para posicionar ou fechar garrafões durante a produção, sem controle previsto."},{"item":"4.7.1","f":"F2","descricao_F":"","classificacao_appcc":"PPRO","desdobramento":"O fechamento deve garantir a vedação das embalagens para evitar vazamentos e contaminação da água mineral natural e da água natural.","orientacao_inspetor":"Verificar vedação e vazamentos; conferir critérios de aceitação, testes de fechamento, frequência, registros e segregação das embalagens com falhas. Verificar o funcionamento.","obs_sim":"Foram verificadas as vedações das embalagens do lote [código], com resultados [ensaio/registro] e ausência de vazamentos.","nc_nao":"Foram observadas embalagens com falhas de vedação após o fechamento, sem segregação e registro de correção adequados."},{"item":"4.7.2","f":"F1","descricao_F":"Revestimentos e porta da sala de envase","classificacao_appcc":"PPR","desdobramento":"O piso, a parede, o teto e a porta da sala de envase devem possuir revestimento liso, de cor clara, impermeável e lavável. A porta deve ser equipada com dispositivo de fechamento automático, ajustada aos batentes e em adequado estado de conservação.","orientacao_inspetor":"Verificar revestimentos lisos, claros, íntegros e laváveis; conferir ajuste e fechamento automático da porta e correção de falhas.","obs_sim":"A sala de envase [linha] apresentava piso, parede, teto e porta íntegros, laváveis e conservados; a porta fechava automaticamente.","nc_nao":"Na sala de envase [linha], foram observadas rachaduras no piso, superfície suja sob a esteira e porta desajustada ao batente."},{"item":"4.7.2","f":"F2","descricao_F":"","classificacao_appcc":"POP","desdobramento":"A sala de envase deve ser mantida em adequado estado de higiene e de conservação.","orientacao_inspetor":"Verificar limpeza e conservação da sala; conferir POP, frequência, registros e correções, articulados à liberação prevista em 4.7.8 F1.","obs_sim":"A sala de envase estava limpa e conservada nos pontos vistoriados. O POP de higienização [código] foi apresentado.","nc_nao":"Na sala de envase [identificação], observou-se sujidade no piso sob o maquinário, em [local ou momento]."},{"item":"4.7.3","f":"F1","descricao_F":"","classificacao_appcc":"PPR","desdobramento":"A adição de dióxido de carbono à água mineral natural ou à água natural, quando houver, deve estar integrada à linha de envase.","orientacao_inspetor":"Verificar integração da adição de CO2 à linha, conexões fechadas e conservação do sistema; conferir aplicabilidade quando não houver gasificação.","obs_sim":"No(a) [local/linha/equipamento], foi comprovado o atendimento a adição de dióxido de carbono à água mineral natural ou à água natural, quando houver, deve estar integrada à linha de envase, por [verificação realizada/documento e data].","nc_nao":"No(a) [local/linha/equipamento], constatou-se ausência ou falha de adição de dióxido de carbono à água mineral natural ou à água natural, quando houver, deve estar integrada à linha de envase. Evidência: [fato constatado, data e identificação]."},{"item":"4.7.4","f":"F1","descricao_F":"","classificacao_appcc":"PPR","desdobramento":"Na sala de envase devem ser adotadas medidas para minimizar o risco de contaminação.","orientacao_inspetor":"Verificar as medidas adotadas na sala de envase para minimizar o risco de contaminação. Evidências documentais: registros de limpeza de filtros e aparelhos de climatização, compatíveis com PMOC quando aplicável, além das condições reais de prevenção da contaminação.","obs_sim":"A sala de envase [linha] possuía medidas documentadas de prevenção da contaminação, com acompanhamento da limpeza e do estado das superfícies.","nc_nao":"Na sala [linha], havia acúmulo de água próximo ao maquinário e condensação em paredes, sem controle demonstrado durante o envase."},{"item":"4.7.4","f":"F2","descricao_F":"Piso, ralo, luminárias e ventilação","classificacao_appcc":"PPR","desdobramento":"critérios selecionáveis abaixo","orientacao_inspetor":"\n1) Verificar inclinação do piso, escoamento, ausência de empoçamento e correção das falhas.\n2) Verificar ralo sifonado, integridade e fechamento da tampa escamoteável; conferir limpeza, manutenção e correções.\n3) Verificar proteção e integridade das luminárias; conferir manutenção e correção de falhas.\n4) Verificar ventilação, condensação e proteção do produto exposto; conferir manutenção, limpeza dos filtros, monitoramento ambiental e correções. Evidências documentais: registros de limpeza de filtros e aparelhos de climatização, compatíveis com PMOC quando aplicável, além das condições reais de prevenção da contaminação.","obs_sim":"Na sala [linha], o piso escoava para ralo sifonado com tampa escamoteável funcional; luminárias estavam protegidas e filtros da climatização tinham registros de limpeza.","nc_nao":"A sala [linha] apresentava ralo sem tampa escamoteável e ausência de registros de limpeza dos filtros do ar-condicionado; registrar também qualquer condensação observada."},{"item":"4.7.5","f":"F1","descricao_F":"","classificacao_appcc":"PPR","desdobramento":"O acesso à sala de envase deve ser restrito e realizado exclusivamente por uma antessala.","orientacao_inspetor":"Verificar restrição de acesso e entrada exclusivamente pela antesala; conferir supervisão e correção de falhas.","obs_sim":"O acesso à sala de envase ocorria exclusivamente pela antessala [código], cuja porta se ajustava ao batente e fechava adequadamente.","nc_nao":"Na antessala da linha [código], a mola da porta não promovia o fechamento e havia folgas junto ao batente, permitindo comunicação com ambiente externo."},{"item":"4.7.5","f":"F2","descricao_F":"A antessala da sala de envase deve possuir:","classificacao_appcc":"PPR","desdobramento":"critérios selecionáveis abaixo","orientacao_inspetor":"\n1) Verificar se o lavatório é de uso exclusivo para a higiene das mãos.\n2) Testar o acionamento da torneira sem contato manual.\n3) Verificar disponibilidade, identificação e reposição do sabonete líquido inodoro.\n4) Verificar disponibilidade, identificação e validade do produto antisséptico.\n5) Verificar disponibilidade, funcionamento e condições higiênicas do sistema de secagem sem contato manual.","obs_sim":"Na antessala [código], foram testados lavatório exclusivo, torneira sem contato manual, sabonete inodoro, antisséptico e sistema de secagem sem contato, todos em funcionamento.","nc_nao":"O sistema de secagem das mãos da antessala [código] estava inoperante; foram encontradas toalhas armazenadas sem proteção, sem atendimento integral à estrutura prevista."},{"item":"4.7.6","f":"F1","descricao_F":"Uniformes da sala de envase","classificacao_appcc":"POP","desdobramento":"Os funcionários que trabalham na sala de envase devem utilizar uniformes limpos, que devem ser trocados diariamente e serem de uso exclusivo para essa área.","orientacao_inspetor":"Verificar uniformes limpos, troca diária e uso exclusivo na sala de envase; conferir rotina de troca e supervisão.","obs_sim":"Os operadores da linha [código] utilizavam uniformes limpos e exclusivos, com registros de trocas e orientação de uso.","nc_nao":"No envase [linha], funcionários estavam sem a paramentação prevista no POP ou utilizavam roupas não exclusivas para a sala."},{"item":"4.7.8","f":"F1","descricao_F":"","classificacao_appcc":"PCC","desdobramento":"A sala de envase e os equipamentos devem ser higienizados quantas vezes forem necessárias e imediatamente após o término do trabalho.","orientacao_inspetor":"Conferir POP e registros por linha de envase e tipo de embalagem, higienização de reservatórios, conexões, tubulações, mangueiras, bicos e demais superfícies de contato; verificar concentração/tempo dos saneantes e sua remoção, quando aplicável, além da validação da eficácia microbiológica e critérios de liberação. O não atendimento do PCC implica alto risco do processo por perigo microbiológico ou resíduos químicos.","obs_sim":"A higienização de bicos, mangueiras e conexões da linha [código] foi comprovada pelo POP [número], registros [datas] e verificação de eficácia [método/resultado].","nc_nao":"Na linha de envase [código], os equipamentos apresentavam sujidades e não foram apresentados registros de higienização no início ou término da operação; avaliar o controle do perigo microbiológico e dos resíduos químicos quando aplicável."},{"item":"4.7.8","f":"F2","descricao_F":"","classificacao_appcc":"PC","desdobramento":"Quando aplicável, a higienização deve contemplar o desmonte dos equipamentos na freqüência definida pelo estabelecimento industrial.","orientacao_inspetor":"Conferir plano e registros de desmonte do reservatório/pulmão, conexões, tubulações desmontáveis, mangueiras, vedações e bicos, conforme necessidade e frequência validadas. Verificar acesso às superfícies, inspeção, limpeza, correções, remontagem higiênica e liberação conforme o PCC de higienização 4.7.8 F1. Evidências documentais: POP e registros de higienização e manutenção dos sistemas de envase de retornáveis e descartáveis; identificação de responsáveis e capacitação.","obs_sim":"O desmonte das conexões, bicos e mangueiras da linha [código] foi registrado em [data], com inspeção e remontagem higiênica.","nc_nao":"Não foram apresentados os registros de desmonte e higienização dos equipamentos de envase da linha [código], apesar da frequência definida em procedimento."},{"item":"4.10.1","f":"F1","descricao_F":"F1 — Implementação E documentação do controle de qualidade","classificacao_appcc":"PPR","desdobramento":"F1 — Verificar os DOIS critérios: (1) IMPLEMENTAÇÃO do controle de qualidade, demonstrada por atividades de coleta, ensaios, equipamentos, profissionais, controles e registros executados; (2) DOCUMENTAÇÃO do controle de qualidade, demonstrada por Manual do Laboratório, POPs, procedimentos e métodos, plano de amostragem, resultados, calibrações e demais registros aplicáveis. Resposta única ao F1: SIM somente se ambos os critérios aplicáveis estiverem atendidos.","orientacao_inspetor":"No mesmo F1, conferir IMPLEMENTAÇÃO e DOCUMENTAÇÃO separadamente. Implementação: constatar execução dos controles, ensaios, equipamentos, pessoal, calibrações e registros reais. Documentação: verificar Manual do Laboratório, POPs, métodos, plano de amostragem, formulários, resultados, certificados e rastreabilidade. Registrar qual dos dois critérios foi atendido ou não. Não aceitar documentação sem execução nem execução sem documentação exigida.","obs_sim":"IMPLEMENTAÇÃO: controle de qualidade executado para [água/embalagens/CO₂, se aplicável], comprovado por [ensaios, equipamentos, profissionais e registros], período [datas]. DOCUMENTAÇÃO: apresentados [Manual do Laboratório, POPs, métodos, plano de amostragem, resultados e certificados] com identificação [números/datas].","nc_nao":"Selecionar o(s) critério(s) não atendido(s): IMPLEMENTAÇÃO — não comprovada a execução de [ensaio/controle/calibração/atividade] no período [datas]. DOCUMENTAÇÃO — ausente ou incompleto [manual/POP/método/plano/registro/laudo/certificado] do controle de qualidade.","criterios_F1":["Implementação do controle de qualidade","Documentação do controle de qualidade"]},{"item":"4.10.2","f":"F1","descricao_F":"Laboratório próprio e/ou terceirizado","classificacao_appcc":"PPR","desdobramento":"critérios selecionáveis abaixo","orientacao_inspetor":"\n1) Verificar instalações, métodos, equipamentos, pessoal e registros do laboratório próprio. Justificar NA somente quando não utilizado e o escopo estiver integralmente coberto por laboratório externo.\n2) Conferir identificação do laboratório, escopo, métodos, laudos e rastreabilidade. A análise externa mensal do produto permanece obrigatória. Evidências documentais: estrutura e registros do laboratório próprio e/ou do terceirizado, contrato vigente com escopo e matriz de responsabilidades e rastreabilidade da coleta.","obs_sim":"Os laudos do laboratório próprio e do terceirizado [período] demonstraram cobertura dos parâmetros e matrizes previstos, com rastreabilidade das coletas.","nc_nao":"A terceirização cobria apenas parte dos ensaios e não foi demonstrada capacidade analítica do laboratório próprio para os parâmetros remanescentes."},{"item":"4.10.2","f":"F2","descricao_F":"Contrato de terceirização","classificacao_appcc":"PPR","desdobramento":"Deve estar disponível contrato vigente das análises terceirizadas, com coleta, transporte, locais, quantidades e parâmetros.","orientacao_inspetor":"Conferir contrato vigente e responsabilidades por coleta e transporte, pontos, quantidades, parâmetros e frequência; confrontar com os laudos. Orçamento não substitui contrato. Evidências documentais: estrutura e registros do laboratório próprio e/ou do terceirizado, contrato vigente com escopo e matriz de responsabilidades e rastreabilidade da coleta.","obs_sim":"Foi apresentado contrato de análises terceirizadas [referência/data], definindo coleta, transporte, frequência, locais, parâmetros e responsabilidade.","nc_nao":"Foram apresentadas notas fiscais de análises laboratoriais, porém não o contrato vigente com o escopo e as responsabilidades da terceirização."},{"item":"4.10.3","f":"F1","descricao_F":"Produto acabado","classificacao_appcc":"PC","desdobramento":"critérios selecionáveis abaixo","orientacao_inspetor":"\n1) Conferir laudos de cada lote: n=5, c=0 e ausência em 250 mL para coliformes totais; verificar rastreabilidade e resposta a resultados insatisfatórios.\n2) Conferir laudos de cada lote: n=5, c=0 e ausência em 250 mL para Escherichia coli; verificar rastreabilidade e resposta a resultados insatisfatórios.\n3) Conferir laudos de cada lote: n=5, c=0 e ausência em 250 mL para enterococos; verificar rastreabilidade e resposta a resultados insatisfatórios.\n4) Conferir laudos de cada lote: n=5, c=0 e ausência em 250 mL para Pseudomonas aeruginosa; verificar rastreabilidade e resposta a resultados insatisfatórios.\n5) Conferir laudos de cada lote: n=5, c=0 e ausência em 50 mL para esporos de clostrídios sulfito redutores; verificar rastreabilidade e resposta a resultados insatisfatórios.\n6) Conferir laudos de cada lote: n=5, c=0 e ausência em 50 mL para esporos de Clostridium perfringens; verificar rastreabilidade e resposta a resultados insatisfatórios.\n7) Conferir contagem, método, ponto/lote, frequência e critério de aceitação documentado; investigar desvios e tendências. Não presumir limite numérico não definido na norma citada. Evidências documentais: laudos físico-químicos e microbiológicos dos últimos três meses, livro de entrada e retirada das placas, parâmetros, frequências e laudos por lote.","obs_sim":"Os laudos microbiológicos do produto [marca/lote] continham coleta, análise, parâmetro, resultado e conclusão para as cinco unidades amostradas, segundo a regra aplicável.","nc_nao":"Para o lote [código], não foram apresentados resultados completos das cinco unidades previstas para [parâmetro], impossibilitando comprovar o atendimento do plano."},{"item":"4.10.3","f":"F2","descricao_F":"Captação","classificacao_appcc":"PC","desdobramento":"critérios selecionáveis abaixo","orientacao_inspetor":"\n1) Conferir laudos semanais de cada captação, método, identificação, critério de aceitação e investigação de resultados insatisfatórios. Não aplicar n=5 do produto ao ponto de processo.\n2) Conferir laudos semanais de cada captação, método, identificação, critério de aceitação e investigação de resultados insatisfatórios. Não aplicar n=5 do produto ao ponto de processo.\n3) Conferir os registros e indicar a frequência observada para este parâmetro.\n4) Conferir os registros e indicar a frequência observada para este parâmetro.\n5) Conferir os registros e indicar a frequência observada para este parâmetro.\n6) Conferir os registros e indicar a frequência observada para este parâmetro.\n7) Conferir contagem, método, ponto/lote, frequência e critério de aceitação documentado; investigar desvios e tendências. Não presumir limite numérico não definido na norma citada.\nFrequências no guia  —  Diário, Semanal ou Outro Evidências documentais: laudos físico-químicos e microbiológicos dos últimos três meses, livro de entrada e retirada das placas, parâmetros, frequências e laudos por lote.","obs_sim":"Foram apresentados resultados semanais de [parâmetro] para a captação [identificação], no período [período].","nc_nao":"Para a captação [identificação], não foram apresentados resultados da análise semanal de bactérias heterotróficas no período [período]."},{"item":"4.10.3","f":"F3","descricao_F":"Reservatório","classificacao_appcc":"PC","desdobramento":"critérios selecionáveis abaixo","orientacao_inspetor":"\n1) Conferir laudos semanais de cada reservatório, método, identificação, critério de aceitação e investigação de resultados insatisfatórios. Não aplicar n=5 do produto ao ponto de processo.\n2) Conferir laudos semanais de cada reservatório, método, identificação, critério de aceitação e investigação de resultados insatisfatórios. Não aplicar n=5 do produto ao ponto de processo.\n3) Conferir os registros e indicar a frequência observada para este parâmetro.\n4) Conferir laudos semanais de cada reservatório, método, identificação, critério de aceitação e investigação de resultados insatisfatórios. Não aplicar n=5 do produto ao ponto de processo.\n5) Conferir os registros e indicar a frequência observada para este parâmetro.\n6) Conferir os registros e indicar a frequência observada para este parâmetro.\n7) Conferir contagem, método, ponto/lote, frequência e critério de aceitação documentado; investigar desvios e tendências. Não presumir limite numérico não definido na norma citada.\nFrequências no guia  —  Diário, Semanal ou Outro Evidências documentais: laudos físico-químicos e microbiológicos dos últimos três meses, livro de entrada e retirada das placas, parâmetros, frequências e laudos por lote.","obs_sim":"Foram apresentados resultados semanais de [parâmetro] para o reservatório [identificação], no período [período].","nc_nao":"Não foram apresentados resultados semanais de [parâmetro] para o reservatório [identificação] no período [período]."},{"item":"4.10.3","f":"F5","descricao_F":"Cinco análises mensais terceirizadas de um lote envasado","classificacao_appcc":"PC","desdobramento":"Devem ser encaminhadas mensalmente cinco amostras do mesmo lote envasado para análise microbiológica em laboratório externo terceirizado.","orientacao_inspetor":"Conferir cinco amostras do mesmo lote por mês e os sete parâmetros microbiológicos da Portaria: coliformes totais, E. coli, enterococos, P. aeruginosa, esporos sulfito redutores, esporos de C. perfringens e heterotróficas. Evidências documentais: laudos físico-químicos e microbiológicos dos últimos três meses, livro de entrada e retirada das placas, parâmetros, frequências e laudos por lote.","obs_sim":"Foi apresentado o laudo terceirizado de [mês/ano], relativo a cinco unidades de um lote de produto acabado [marca/lote].","nc_nao":"O laboratório externo analisou somente uma unidade no mês [data], sem demonstrar a amostragem de cinco unidades de um lote exigida no guia."},{"item":"4.10.3","f":"F6","descricao_F":"Cinco unidades analisadas de todos os lotes envasados","classificacao_appcc":"PC","desdobramento":"Todos os lotes envasados devem ser analisados em cinco unidades, abrangendo início, meio e término do envase.","orientacao_inspetor":"Confrontar produção, lotes e laudos: cinco unidades por lote, início/meio/término, seis parâmetros da IN 161/2022 e heterotróficas da Portaria. O laudo externo mensal não substitui o controle de todos os lotes. Evidências documentais: laudos físico-químicos e microbiológicos dos últimos três meses, livro de entrada e retirada das placas, parâmetros, frequências e laudos por lote.","obs_sim":"Os registros de todos os lotes [período] apresentaram a análise de cinco unidades por lote, rastreáveis aos respectivos produtos envasados.","nc_nao":"O controle documentou apenas uma unidade por lote ou não demonstrou ensaio de cinco unidades em todos os lotes [período]."},{"item":"4.10.4","f":"F1","descricao_F":"","classificacao_appcc":"PPRO","desdobramento":"O estabelecimento industrial deve estabelecer plano de amostragem, especificando o número de amostras, o local de coleta, os parâmetros analíticos e a frequência a ser realizada, envolvendo as diversas etapas da industrialização.","orientacao_inspetor":"Conferir pontos, número de amostras, parâmetros e frequências do plano; incluir verificação pós-higienização, critérios de liberação e controle do ar de sopro, quando aplicável. Evidências documentais: plano de amostragem previsto na Portaria SUVISA 4325/2025 e execução demonstrada por planilhas e laudos.","obs_sim":"O plano de amostragem [versão/data] descreve matrizes, pontos de coleta, parâmetros, frequências, número de unidades e critérios de aceitação.","nc_nao":"O plano de amostragem apresentado era de versão antiga e não contemplava as frequências, os parâmetros e os números de unidades exigidos no guia atualizado."},{"item":"4.10.4","f":"F2","descricao_F":"","classificacao_appcc":"PPRO","desdobramento":"O estabelecimento industrial deve executar o plano de amostragem e definir os limites de aceitação a serem determinados nas amostras coletadas, segundo o plano estabelecido.","orientacao_inspetor":"Comparar coletas e ensaios com o plano; conferir limites, laudos por lote, rastreabilidade, retenção prevista, autorização de liberação e resposta aos resultados insatisfatórios. Evidências documentais: plano de amostragem previsto na Portaria SUVISA 4325/2025 e execução demonstrada por planilhas e laudos.","obs_sim":"Os registros de [período] demonstram a execução do plano de amostragem, incluindo os lotes e pontos selecionados.","nc_nao":"Os laudos do período [datas] não comprovam a execução do plano estabelecido, especialmente [ponto/parâmetro/número de amostras]."},{"item":"4.10.5","f":"F1","descricao_F":"","classificacao_appcc":"PC","desdobramento":"A água mineral natural ou a água natural envasada deve apresentar composição equivalente à respectiva água emergente da fonte ou poço, conforme especificada nas análises laboratoriais efetuadas pelo órgão competente do Ministério das Minas e Energia.","orientacao_inspetor":"Comparar composição da água envasada com a da respectiva fonte ou poço e com os laudos de referência; conferir identificação e investigação das diferenças. Evidências documentais: último laudo LAMIN de cada captação e último laudo físico-químico dos produtos envasados conforme RDC 717/2022.","obs_sim":"A comparação entre os laudos [números/datas] da fonte [código] e do produto [marca] demonstrou equivalência da composição declarada.","nc_nao":"Não foi demonstrada a comparação da composição físico-química do produto [marca] com a fonte [código], conforme laudos aplicáveis."},{"item":"4.10.5","f":"F2","descricao_F":"","classificacao_appcc":"PC","desdobramento":"Foram apresentados os laudos físico-químicos de todos os produtos envasados, abrangendo os parâmetros aplicáveis da RDC 717/2022.","orientacao_inspetor":"Conferir laudos completos, identificação dos produtos e apresentações, datas, parâmetros e resultados do Anexo I. Relacionar cada produto à captação de origem; verificar a execução e frequência no CQ03 F15. Evidências documentais: último laudo LAMIN de cada captação e último laudo físico-químico dos produtos envasados conforme RDC 717/2022.","obs_sim":"Foi apresentado laudo físico-químico anual [número/data] do produto envasado [marca/apresentação], conforme escopo exigível.","nc_nao":"Não foi apresentado o laudo físico-químico anual aplicável ao produto envasado [marca/apresentação]."},{"item":"4.10.5","f":"F3","descricao_F":"","classificacao_appcc":"PC","desdobramento":"Foram apresentados os laudos oficiais LAMIN das respectivas fontes ou poços, com correspondência a todos os produtos envasados.","orientacao_inspetor":"Conferir laudo oficial de cada fonte ou poço, identificação, data e situação perante a ANM, inclusive prorrogação formal quando aplicável. Vincular todos os produtos à fonte e comparar a composição; o LAMIN é referência da fonte, distinto do laudo do produto acabado. Evidências documentais: último laudo LAMIN de cada captação e último laudo físico-químico dos produtos envasados conforme RDC 717/2022.","obs_sim":"Foi apresentado laudo LAMIN [número/data] para a captação [código], correspondente ao produto envasado [marca].","nc_nao":"Não foi apresentado o laudo LAMIN da captação [código], ou o laudo não correspondia à fonte do produto [marca]."},{"item":"4.10.6","f":"F1","descricao_F":"","classificacao_appcc":"PC","desdobramento":"Em caso de resultados analíticos insatisfatórios ou outros desvios, o estabelecimento deve adotar e demonstrar as medidas cabíveis de investigação, controle do processo e proteção dos lotes afetados.","orientacao_inspetor":"Verificar separadamente, quando pertinente: (1) investigação e identificação da causa; (2) delimitação dos lotes afetados e rastreabilidade; (3) bloqueio ou quarentena; (4) retenção de lotes; (5) reanálise com amostragem prevista no POP; (6) higienização e correção do processo afetado; (7) definição do destino de produto e descarte, quando cabível; (8) recolhimento/recall, quando aplicável; (9) medidas corretivas e preventivas; (10) verificação da eficácia; (11) critérios técnicos de retomada ou liberação. Considerar registros do SAC, reclamações e devoluções, além do POP de Desvios e do POP de Recall. Nem toda medida se aplica a todos os desvios: justificar a seleção.","obs_sim":"Para o desvio [parâmetro/data], foram demonstrados investigação, delimitação de lotes, bloqueio, reanálise, correção, destino e verificação de eficácia antes da liberação.","nc_nao":"Após resultado insatisfatório, a reanálise ocorreu em número de amostras inferior ao previsto no POP, sem bloqueio comprovado dos lotes potencialmente afetados ou registro da investigação."},{"item":"4.10.6","f":"F2","descricao_F":"","classificacao_appcc":"PPR","desdobramento":"As medidas adotadas e sua avaliação de eficácia devem estar documentadas, com rastreabilidade dos lotes e decisão final de destino ou liberação.","orientacao_inspetor":"Solicitar POP de Desvios e Ações Corretivas e POP de Recolhimento (Recall); conferir formulários de desvio, registros do SAC e devoluções, plano de retenção de lotes descartáveis e retornáveis, quarentena, reanálises, avaliação técnica, responsáveis e datas. Confirmar evidência do encerramento do desvio e eficácia.","obs_sim":"Foram apresentados POP de desvios, POP de recolhimento, registros de SAC, retenção dos lotes e encerramento de ações corretivas com avaliação de eficácia.","nc_nao":"Não foram apresentados POP de Recall, registros de reclamações do SAC ou documentação da retenção e destinação dos lotes afetados, prejudicando a rastreabilidade."},{"item":"4.12.6","f":"F1","descricao_F":"","classificacao_appcc":"PC","desdobramento":"O estabelecimento industrial deve possuir certificado que comprove a qualidade do dióxido de carbono correspondente a cada carga, lote ou cilindro utilizado no envase.","orientacao_inspetor":"Confirmar se há gaseificação. Quando houver, identificar o cilindro ou sistema em uso, lote/carga, fabricante, número do certificado, data, validade e correspondência do certificado com o gás efetivamente utilizado. Documentar NA quando não houver adição de CO₂.","obs_sim":"O certificado de qualidade [número] corresponde ao lote [código] e ao cilindro de CO₂ em uso [identificação], com validade [data].","nc_nao":"O certificado apresentado pertencia a carga ou lote de CO₂ diferente do cilindro em uso [identificação], sem comprovação da qualidade deste gás."},{"item":"4.11.1","f":"F1","descricao_F":"F1 — Supervisão E capacitação periódica dos manipuladores","classificacao_appcc":"PPR","desdobramento":"F1 — Verificar os DOIS critérios: (1) SUPERVISÃO do cumprimento das Boas Práticas pelos manipuladores durante as atividades; (2) CAPACITAÇÃO PERIÓDICA dos manipuladores em higiene pessoal, manipulação higiênica, doenças transmitidas por alimentos e BPF, com evidências da realização. Resposta única ao F1: SIM somente se ambos os critérios aplicáveis estiverem atendidos.","orientacao_inspetor":"No mesmo F1, verificar SUPERVISÃO e CAPACITAÇÃO PERIÓDICA separadamente. Supervisão: observar práticas e responsável pelo acompanhamento, ações de correção e registros. Capacitação periódica: conferir calendário, conteúdo, datas, instrutor, carga horária, lista de presença e vínculo dos participantes com os processos executados. Registrar qual critério está conforme ou não.","obs_sim":"SUPERVISÃO: constatado acompanhamento das atividades dos manipuladores de [processo] por [função/responsável], com [registros/observação direta]. CAPACITAÇÃO PERIÓDICA: comprovados treinamentos dos manipuladores de [processos] em [datas], com [conteúdo, carga horária e lista de presença].","nc_nao":"Selecionar o(s) critério(s) não atendido(s): SUPERVISÃO — ausente ou ineficaz nas operações de [processo], com evidências [fatos]. CAPACITAÇÃO PERIÓDICA — não comprovada para [manipuladores/processos], período [datas], ou conteúdo/registro insuficiente.","criterios_F1":["Supervisão dos manipuladores","Capacitação periódica dos manipuladores"]},{"item":"4.11.2","f":"F1","descricao_F":"Responsabilidade pela industrialização","classificacao_appcc":"PPR","desdobramento":"critérios selecionáveis abaixo","orientacao_inspetor":"Identificar o responsável pela industrialização e comprovar sua designação, representação e atribuições. Quando a responsabilidade técnica específica for exigível, conferir o CRT e o documento do conselho profissional competente. Para responsabilidade atribuída ao responsável legal ou proprietário, comprovar a função sem dispensar o CRT previsto na norma aplicável.\n1) Conferir identificação, designação, atribuições e atuação do responsável técnico na industrialização. Justificar NA quando a função for exercida pelo responsável legal ou proprietário, sem afastar CRT específico exigido por lei.\n2) Conferir representação legal, identificação, atribuições e atuação na industrialização. Justificar NA quando outra das funções F1–F3 exercer essa responsabilidade.\n3) Conferir condição de proprietário, identificação, atribuições e atuação na industrialização. Justificar NA quando outra das funções F1–F3 exercer essa responsabilidade. Evidências documentais: comprovação da responsabilidade pela industrialização e do profissional exigível pelo conselho competente, inclusive CRT quando aplicável.","obs_sim":"A responsabilidade pela industrialização foi atribuída a [função], com comprovação de designação e atribuições; a responsabilidade técnica exigível foi comprovada por CRT [referência].","nc_nao":"A empresa identificou o responsável pela industrialização, mas não apresentou o CRT exigível para a operação de higienização química de embalagens retornáveis."},{"item":"4.11.2","f":"F2","descricao_F":"Habilitação nos conselhos profissionais","classificacao_appcc":"PPR","desdobramento":"critérios selecionáveis abaixo","orientacao_inspetor":"\n1) Conferir registro, atribuição e documento de responsabilidade no CRQ. Nas envasadoras do RJ com retornáveis abrangidos pela Lei 10.003/2023, conferir CRT do processamento químico industrial de higienização habilitado no CRQ-III; outro conselho não substitui essa exigência.\n2) Conferir registro e regularidade no CRBio, atribuições compatíveis e anotação de responsabilidade quando exigida. Justificar NA se não houver atividade sob essa responsabilidade; não substituir a exigência específica de CRQ por CRBio.\n3) Identificar conselho e atividade; conferir registro, habilitação, atribuição e termo ou anotação de responsabilidade exigível. Justificar NA se não aplicável; não equiparar registros de conselhos diferentes sem base legal. Evidências documentais: comprovação da responsabilidade pela industrialização e do profissional exigível pelo conselho competente, inclusive CRT quando aplicável.","obs_sim":"Foi verificada habilitação no conselho profissional competente [registro/certidão], conforme a atividade efetivamente exercida.","nc_nao":"Não foi apresentada prova de habilitação no conselho profissional competente para o responsável indicado pela atividade [identificação]."},{"item":"4.11.3","f":"F1","descricao_F":"F1 — Capacitação de 40 horas e conferência de curso com mais de dois anos","classificacao_appcc":"PPR","desdobramento":"F1 — Verificar os DOIS critérios em uma única frase: (1) CAPACITAÇÃO INICIAL do responsável pela industrialização, comprovada por curso com CARGA HORÁRIA MÍNIMA DE 40 HORAS e conteúdos pertinentes; (2) CURSO CONCLUÍDO HÁ MAIS DE DOIS ANOS: verificar a data de conclusão e a comprovação de atualização/reciclagem conforme o critério adotado no Guia. Se o curso tiver até dois anos, registrar que a segunda verificação não se aplica. O F1 permanece único.","orientacao_inspetor":"Conferir o certificado de 40 HORAS do responsável pela industrialização: identificação do participante, entidade, data, carga horária e conteúdos. Comparar a data de conclusão com a data da inspeção. Se o curso tiver MAIS DE DOIS ANOS, conferir documento de atualização/reciclagem aplicável e registrar sua data; se tiver até dois anos, indicar 'não se aplica' para esse subcritério. Não criar outro F pontuável.","obs_sim":"CAPACITAÇÃO DE 40 HORAS: apresentado certificado de [responsável pela industrialização], [entidade], concluído em [data], carga horária [40 horas ou mais] e conteúdo [temas]. CURSO COM MAIS DE DOIS ANOS: [atualização comprovada por certificado de data e identificação / não se aplica, pois curso concluído em data há até dois anos].","nc_nao":"Selecionar o(s) critério(s) não atendido(s): CAPACITAÇÃO DE 40 HORAS — inexistente certificado ou carga horária inferior a 40 horas para [responsável]. CURSO COM MAIS DE DOIS ANOS — curso de [data] sem comprovação da atualização/reciclagem exigida pelo critério adotado no Guia.","criterios_F1":["Capacitação de 40 horas do responsável pela industrialização","Curso concluído há mais de dois anos: atualização/reciclagem (ou não se aplica)"]},{"item":"4.11.4","f":"F1","descricao_F":"F1 — Certificados dos manipuladores E do responsável pela industrialização","classificacao_appcc":"PPR","desdobramento":"F1 — Verificar os DOIS critérios: (1) CERTIFICADOS DE CAPACITAÇÃO DOS MANIPULADORES que atuam em captação, condução, reservatórios, recepção, higienização e envase, conforme aplicável; (2) CERTIFICADO DE CAPACITAÇÃO DO RESPONSÁVEL PELA INDUSTRIALIZAÇÃO, com nome, data, carga horária e conteúdo. Resposta única ao F1: SIM somente se ambos os critérios aplicáveis estiverem atendidos.","orientacao_inspetor":"No mesmo F1, conferir CERTIFICADOS DOS MANIPULADORES por processo aplicável (captação, condução, reservatórios, recepção, higienização das embalagens e envase) e CERTIFICADO DO RESPONSÁVEL PELA INDUSTRIALIZAÇÃO. Registrar nome, função, data, carga horária, conteúdo, processo e vínculo. O critério de curso de 40 horas e curso com mais de dois anos permanece avaliado no 4.11.3, sem gerar F2 no 4.11.4.","obs_sim":"CERTIFICADOS DOS MANIPULADORES: apresentados para [processos e funcionários], com [datas, carga horária e conteúdo]. CERTIFICADO DO RESPONSÁVEL PELA INDUSTRIALIZAÇÃO: apresentado para [nome], concluído em [data], com [carga horária e conteúdos].","nc_nao":"Selecionar o(s) critério(s) não atendido(s): CERTIFICADOS DOS MANIPULADORES — não apresentados para [funcionários/processos]. CERTIFICADO DO RESPONSÁVEL PELA INDUSTRIALIZAÇÃO — não apresentado ou sem comprovação de [data/carga horária/conteúdo] de [nome/função].","criterios_F1":["Certificados dos manipuladores","Certificado do responsável pela industrialização"]}]};
const RECS=new Map(DATA.verificacoes.map(r=>[r.item+'/'+r.f,r]));
const SPECIAL={
 '4.3.3':{'F1':[0,1,2,3,4,5]},
 '4.7.4':{'F1':[0],'F2':[4,1,2,3]},
 '4.7.5':{'F1':[0],'F2':[1,4,2,5,3]},
 '4.10.2':{'F1':[0,1],'F2':[2]},
 '4.11.2':{'F1':[0,1,2],'F2':[3,4,5]},
 '4.10.3':{'F1':[0,1,2,3,4,5,6],'F2':[7,8,14,17,18,19,9],
   'F3':[10,11,20,12,21,22,13],'F5':[15],'F6':[16]}
};
const EXPAND=new Set();
const changed=new Set(), missing=[];
function cloneForF2(phrase,r){
 const p={...phrase};delete p.fieldSuffix;delete p.revision;
 p.text=r.desdobramento;p.guidance=r.orientacao_inspetor;
 return p;
}
function patchPhrase(row,index,record,keepSpecificText,firstGuide){
 const source=row.phrases[index];
 if(!source)return;
 const previousText=String(source.text||'');
 if(!keepSpecificText)source.text=record.desdobramento;
 const revised=String(record.orientacao_inspetor||'').trim();
 const guidanceFor=(specific)=>keepSpecificText&&specific&&revised&&!revised.includes(specific)
  ?revised+'\\nVerificação específica: '+specific:revised||specific;
 source.guidance=guidanceFor(String(source.guidance||'').trim());
 for(const scope of row.scopes){
  const f=scope.phrases[index];if(!f)continue;
  // Manter o detalhamento especifico de cada F ou linha, sem perder a orientacao atualizada.
  if(!keepSpecificText&&String(f.text||'')===previousText)f.text=record.desdobramento;
  f.guidance=guidanceFor(String(f.guidance||'').trim());
 }
}
try{
if(typeof BPF_PHRASES==='undefined'||!Array.isArray(BPF_PHRASES))throw Error('Estrutura de frases não encontrada');
for(const page of BPF_PHRASES){
 for(const row of page.rows){
  const code=row.code,group=SPECIAL[code];
  if(EXPAND.has(code)&&row.phrases.length===1){
   const second=RECS.get(code+'/F2');
   if(second){
    row.phrases.push(cloneForF2(row.phrases[0],second));
    for(const scope of row.scopes)scope.phrases.push(cloneForF2(scope.phrases[0],second));
   }
  }
  const applicable=DATA.verificacoes.filter(r=>r.item===code);
  for(const record of applicable){
   const number=Number(record.f.replace('F',''));
   const indices=group?.[record.f]||(Number.isInteger(number)?[number-1]:[]);
   if(!indices.length){missing.push(code+'/'+record.f);continue}
   for(let k=0;k<indices.length;k++){
    const idx=indices[k];
    if(!row.phrases[idx]){missing.push(code+'/'+record.f+'#'+idx);continue}
    const grouped=!!group&&indices.length>1;
    // Preserve detailed sub-requirement texts in composite F and replace their common guidance.
    patchPhrase(row,idx,record,grouped,k===0);
    changed.add(code+'/'+record.f);
   }
  }
 }
}
window.__bpfRevisaoFResumo={itens:new Set([...changed].map(k=>k.split('/')[0])).size,
 desdobramentos:changed.size,pendentes:[...new Set(missing)],semAlterarDescricaoLegal:true};
}catch(error){window.__bpfRevisaoFErro=String(error);return;}

function patchAfterGuideReady(){
 if(typeof BPF_EXAMPLE_REVISIONS==='undefined'||typeof bpfPanels!=='function')return false;
 if(window.__bpfRevisaoFPosCarregamento)return true;
 window.__bpfRevisaoFPosCarregamento=true;
 let updatedExamples=0;
 for(const page of BPF_PHRASES)for(const row of page.rows){
  for(const panel of bpfPanels(page,row)){
   const num=panel.id+1;
   const docF=row.code==='4.10.3'&&num>=4?'F'+(num+1):'F'+num;
   const record=RECS.get(row.code+'/'+docF);
   if(!record)continue;
   const key=bpfExampleKey(page,row.code,panel);
   const target=BPF_EXAMPLE_REVISIONS.get(key);
   if(!target)continue;
   target.sim=record.obs_sim;
   target.nao=record.nc_nao;
   const entry=BPF_INSPECTOR_BY_KEY.get(key);
   if(entry){
    entry.original.sim=record.obs_sim;
    entry.original.nao=record.nc_nao;
    for(const ref of entry.refs){ref.sim=record.obs_sim;ref.nao=record.nc_nao}
   }
   updatedExamples++;
  }
 }
 if(typeof BPF_NC_DEFINITIONS!=='undefined'){
  for(const [code,value]of Object.entries(DATA.definicoes)){
   if(BPF_NC_DEFINITIONS[code]){
    BPF_NC_DEFINITIONS[code].text=value.replace(new RegExp('^'+code+'\\s*[—–-]\\s*'),'');
   }
  }
 }
 // F2 separados e detalhamento original preservado sem repetir a mesma subverificação no F1.
 if(typeof bpfF1Checks==='function'){
  const old=bpfF1Checks;
  bpfF1Checks=function(row,scope){
   const entries=old(row,scope);
   if(['4.10.1','4.11.1','4.11.3'].includes(row.code))return entries.slice(0,1);
   if(row.code==='4.11.4')return entries.slice(0,6);
   return entries;
  };
 }
 // Migrar respostas dos antigos subcampos F1 para F2 somente quando F2 não tiver resposta.
 if(typeof values!=='undefined'&&typeof bpfPhraseName==='function'){
  const moves={'4.10.1':['ControleQualidade',2],'4.11.1':['Responsaveis',2],
   '4.11.3':['Responsaveis',2],'4.11.4':['Responsaveis',7]};
  for(const page of BPF_PHRASES)for(const row of page.rows){
   const move=moves[row.code];if(!move)continue;
   for(const scope of row.scopes){
    const old=bpfPhraseName(scope,0)+'_'+move[0]+'_'+move[1];
    const next=bpfPhraseName(scope,1);
    if(!values[next]&&['1','0','2'].includes(values[old]))values[next]=values[old];
   }
  }
 }
 if(typeof bpfInspectorApplySaved==='function'){
  // Existing user-specific revisions remain recoverable; new texts are the Guide defaults.
  if(typeof bpfInspectorLastApplied!=='undefined')bpfInspectorLastApplied=null;
  bpfInspectorApplySaved();
 }
 window.__bpfRevisaoFResumo.exemplosAtualizados=updatedExamples;
 window.__bpfRevisaoFResumo.definicoes=Object.keys(DATA.definicoes).length;
 if(typeof window.Guia?.recalc==='function')window.Guia.recalc();
 return true;
}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',patchAfterGuideReady,{once:true});
else patchAfterGuideReady();
})();